#nullable enable // autogenerated

using System.Collections.Generic;
using System.Linq;
using MVZ2.Managers;
using MVZ2.Saves;
using MVZ2.Scenes;
using MVZ2.UI.Customize;
using MVZ2Logic.Customize;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Customize
{
    public class CustomizeController : MainScenePage
    {
        public override void Display()
        {
            base.Display();
            UpdateCustomizeItems();

            DisplayIndex();
        }
        public void DisplayIndex()
        {
            ui.SetIndexVisible(true);
            HidePages();
        }
        private void Awake()
        {
            ui.OnReturnClick += OnReturnClickCallback;
            ui.OnButtonClick += OnButtonClickCallback;
        }
        private void OnReturnClickCallback()
        {
            Return();
        }
        private void OnButtonClickCallback(int index)
        {
            if (index < 0 || index >= pagesID.Count)
                return;
            var pageID = pagesID[index];
            if (pages.TryGetValue(pageID, out var page))
            {
                ui.SetIndexVisible(false);
                page.Display(uiCamera);
            }
        }
        private void OnPageReturnCallback()
        {
            ui.SetIndexVisible(true);
        }
        private void HidePages()
        {
            foreach (var pair in pages)
            {
                pair.Value.Hide();
            }
        }
        private void UpdateCustomizeItems()
        {
            var newPagesID = Main.ResourceManager.GetAllCustomizePageMetasID();
            var removeIDs = pagesID.Except(newPagesID).ToList();


            foreach (var metaID in newPagesID)
            {
                var prefab = GetCustomizePagePrefab(metaID);
                if (prefab != null)
                {
                    if (pagesID.Contains(metaID))
                        continue;
                    var pageObject = Instantiate(prefab.gameObject, pagesRoot);
                    var controller = pageObject.GetComponent<CustomizePageController>();
                    if (controller == null)
                        continue;
                    controller.OnReturn += OnPageReturnCallback;
                    pagesID.Add(metaID);
                    pages.Add(metaID, controller);
                }
                else
                {
                    removeIDs.Add(metaID);
                }
            }
            foreach (var metaID in removeIDs)
            {
                pagesID.Remove(metaID);
                if (pages.TryGetValue(metaID, out var page))
                {
                    page.OnReturn -= OnPageReturnCallback;
                    Destroy(page.gameObject);
                    pages.Remove(metaID);
                }
            }

            List<string> buttonNames = new List<string>();
            foreach (var pageID in pagesID)
            {
                var meta = Main.ResourceManager.GetCustomizePageMeta(pageID);
                if (meta == null)
                    continue;
                buttonNames.Add(Main.LanguageManager._(meta.ButtonText));
            }
            ui.SetButtons(buttonNames.ToArray());
        }
        private CustomizePageController? GetCustomizePagePrefab(NamespaceID metaID)
        {
            var meta = Main.ResourceManager.GetCustomizePageMeta(metaID);
            if (meta == null)
                return null;
            if (!meta.Unlock.IsNullOrMeetsConditions(Main.SaveManager))
                return null;
            return Main.ResourceManager.GetCustomizePagePrefab(meta.PrefabPath);
        }
        public static MainManager Main => MainManager.Instance;
        [SerializeField]
        private Camera uiCamera = null!;
        [SerializeField]
        private CustomizeUI ui = null!;
        [SerializeField]
        private Transform pagesRoot = null!;
        private readonly List<NamespaceID> pagesID = new();
        private readonly Dictionary<NamespaceID, CustomizePageController> pages = new();
    }
}
